draw((0,0)--(4,0)--(4,4)--(0,4)--cycle);
draw((0,3)--(0,4)--(1,4)--(1,3)--cycle);
draw((1,3)--(1,4)--(2,4)--(2,3)--cycle);
draw((2,3)--(2,4)--(3,4)--(3,3)--cycle);
